inline bool captured(const QString &key){
    static const QStringList skipped{"ai/","profiles/","performance/","moduleWindows/","defaults/","recent","lastDirectory","files/","genki/","interface/colors"};
    for(const auto &prefix:skipped)if(key.startsWith(prefix))return false;
    return true;
}
inline QJsonValue encode(const QVariant &value){
    switch(value.typeId()){
    case QMetaType::Bool:return value.toBool();
    case QMetaType::Int:case QMetaType::UInt:case QMetaType::LongLong:case QMetaType::ULongLong:return value.toLongLong();
    case QMetaType::Double:case QMetaType::Float:return value.toDouble();
    case QMetaType::QByteArray:return QJsonObject{{"base64",QString::fromLatin1(value.toByteArray().toBase64())}};
    case QMetaType::QPointF:case QMetaType::QPoint:{const auto point=value.toPointF();return QJsonObject{{"point",QJsonArray{point.x(),point.y()}}};}
    case QMetaType::QStringList:return QJsonArray::fromStringList(value.toStringList());
    default:return value.toString();
    }
}
inline QVariant decode(const QJsonValue &value){
    if(value.isObject()){const auto object=value.toObject();if(object.contains("base64"))return QByteArray::fromBase64(object["base64"].toString().toLatin1());
        if(object.contains("point")){const auto point=object["point"].toArray();return QPointF(point.at(0).toDouble(),point.at(1).toDouble());}return {};}
    if(value.isArray()){QStringList list;for(const auto &item:value.toArray())list<<item.toString();return list;}
    return value.toVariant();
}
inline QJsonObject capture(QSettings &settings){
    QJsonObject values;for(const auto &key:settings.allKeys())if(captured(key))values[key]=encode(settings.value(key));
    return QJsonObject{{"format","9xd-release-defaults"},{"version",version},{"settings",values}};
}
// Fills in the keys this installation lacks. Runs once per defaults version.
inline void seed(QSettings &settings){
    if(settings.value("defaults/seededVersion",0).toInt()>=version)return;
    const auto root=QJsonDocument::fromJson(embeddedJson()).object();const auto values=root["settings"].toObject();
    for(auto it=values.begin();it!=values.end();++it)if(captured(it.key())&&!settings.contains(it.key())){const auto value=decode(it.value());if(value.isValid())settings.setValue(it.key(),value);}
    settings.setValue("defaults/seededVersion",version);
}
// Classic panel arrangement of a module from the embedded defaults (for Reset Panel Layout), or empty.
inline QByteArray moduleLayout(const QString &id){
    static const auto values=QJsonDocument::fromJson(embeddedJson()).object()["settings"].toObject();
    return decode(values.value("moduleLayouts/v1/"+id)).toByteArray();
}
